css:
.hw-original{--red:#c7000b;--red-dark:#a80009;--red-soft:#fff1f1;--ink:#181818;--text:#333;--muted:#6f7378;--line:#dcdfe3;--soft:#f5f6f7;--soft-2:#eceef0;--font-factor:1;--row-gap:16px}
:where(.hw-original) *{box-sizing:border-box}
:where(.hw-original) button,:where(.hw-original) select{font:inherit}
:where(.hw-original) button{cursor:pointer}
.hw-original{position:absolute;left:50%;top:50%;width:1280px;height:720px;background:#fff;box-shadow:0 14px 50px #27313d26;overflow:hidden;transform-origin:center center;display:none}
.hw-original.active{display:block}
.hw-original h1{position:absolute;left:64px;top:40px;width:1020px;margin:0;font-size:34px;line-height:1.25;font-weight:700;letter-spacing:-.02em}
.hw-original .lead{position:absolute;left:64px;top:94px;width:1060px;margin:0;font-size:calc(17px * var(--font-factor));line-height:1.5;color:#60656b}
.hw-original .template-tag{position:absolute;right:64px;top:47px;min-width:110px;text-align:right;color:var(--red);font-size:13px;font-weight:700;letter-spacing:.04em}
.hw-original .content{position:absolute;left:64px;top:148px;width:1152px;height:472px}
.hw-original .source{position:absolute;left:64px;bottom:24px;width:850px;font-size:12px;line-height:1.4;color:#888d92}
.hw-original .brand{position:absolute;right:76px;bottom:21px;width:118px;height:auto}
:where(.hw-original) .demo-flag{display:inline-block;margin-left:8px;padding:2px 6px;background:#f0f1f2;color:#777c81;font-size:10px;font-weight:400;vertical-align:middle;letter-spacing:0}
:where(.hw-original) .eyebrow{font-size:12px;color:var(--muted);letter-spacing:.08em;font-weight:700;text-transform:uppercase}
:where(.hw-original) .red{color:var(--red)}
:where(.hw-original) .muted{color:var(--muted)}
:where(.hw-original) .pill{display:inline-flex;align-items:center;justify-content:center;border:1px solid var(--line);border-radius:999px;padding:4px 10px;font-size:12px;white-space:nowrap}
:where(.hw-original) .pill.red-pill{border-color:#e8b7ba;background:var(--red-soft);color:var(--red)}
:where(.hw-original) .metric-layout{height:100%;display:grid;grid-template-columns:390px 1fr;gap:28px}
:where(.hw-original) .metric-hero{position:relative;background:var(--ink);color:#fff;padding:34px 34px 28px;display:flex;flex-direction:column;overflow:hidden}
:where(.hw-original) .metric-hero:after{content:"";position:absolute;width:240px;height:240px;border:46px solid #ffffff0a;border-radius:50%;right:-100px;top:-90px}
:where(.hw-original) .metric-hero .hero-label{font-size:18px;font-weight:700}
:where(.hw-original) .metric-hero .hero-value{margin-top:32px;font-size:96px;line-height:1;font-weight:700;letter-spacing:-.06em}
:where(.hw-original) .metric-hero .hero-value small{font-size:34px;letter-spacing:0;margin-left:5px}
:where(.hw-original) .metric-hero .hero-desc{margin-top:16px;font-size:17px;color:#d5d7da}
:where(.hw-original) .metric-hero .hero-delta{margin-top:26px;display:inline-flex;align-items:center;gap:8px;color:#ffb9bd;font-size:15px;font-weight:700}
:where(.hw-original) .metric-hero .hero-bars{margin-top:auto;height:78px;display:flex;align-items:flex-end;gap:10px;border-bottom:1px solid #ffffff2b}
:where(.hw-original) .metric-hero .hero-bars i{display:block;flex:1;background:#55595e}
:where(.hw-original) .metric-hero .hero-bars i:last-child{background:var(--red)}
:where(.hw-original) .metric-grid{display:grid;grid-template-columns:repeat(2,1fr);grid-template-rows:repeat(2,1fr);gap:16px}
:where(.hw-original) .metric-grid.six{grid-template-columns:repeat(3,1fr);grid-template-rows:repeat(2,1fr)}
:where(.hw-original) .metric-grid.six .metric-extra{display:flex}
:where(.hw-original) .metric-three-main{display:contents}
:where(.hw-original) .metric-three-detail{display:none}
:where(.hw-original) .metric-grid.three{grid-template-columns:1fr;grid-template-rows:1.45fr 1fr}
:where(.hw-original) .metric-grid.three .metric-three-main{display:grid;grid-template-rows:repeat(3,1fr);border:1px solid var(--line)}
:where(.hw-original) .metric-grid.three .metric-three-main .metric-card{border:0;border-bottom:1px solid var(--line);padding:14px 20px;display:grid;grid-template-columns:160px 1fr;align-items:center;column-gap:18px}
:where(.hw-original) .metric-grid.three .metric-three-main .metric-card:last-child{border-bottom:0}
:where(.hw-original) .metric-grid.three .metric-three-main .metric-value{grid-column:1;grid-row:1/3;justify-self:center;margin-top:0;font-size:40px}
:where(.hw-original) .metric-grid.three .metric-three-main .metric-label{grid-column:2;grid-row:1;font-size:13px}
:where(.hw-original) .metric-grid.three .metric-three-main .metric-note{grid-column:2;grid-row:2;margin-top:4px;font-size:12px}
:where(.hw-original) .metric-grid.three .metric-three-main .metric-foot{display:none}
:where(.hw-original) .metric-grid.three .metric-three-detail{display:block;border:1px solid var(--line);padding:18px 20px;background:linear-gradient(135deg,#f2f2f2,#e0e0e0)}
:where(.hw-original) .metric-three-detail .detail-title{font-size:15px;font-weight:700;color:var(--red);margin-bottom:8px}
:where(.hw-original) .metric-three-detail p{margin:0;font-size:13px;line-height:1.55;color:#4d4d4d}
:where(.hw-original) .metric-three-columns{display:none}
:where(.hw-original) .metric-grid.three-columns{grid-template-columns:repeat(3,1fr);grid-template-rows:1fr}
:where(.hw-original) .metric-grid.three-columns .metric-three-columns{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;grid-column:1/-1}
:where(.hw-original) .metric-three-item{display:grid;grid-template-rows:160px 1fr;gap:12px}
:where(.hw-original) .metric-three-item .metric-card{height:160px;padding:18px}
:where(.hw-original) .metric-three-item .metric-value{font-size:36px}
:where(.hw-original) .metric-item-detail{padding:14px 15px;border:1px solid var(--line);background:linear-gradient(135deg,#f2f2f2,#e0e0e0);font-size:12px;line-height:1.5;color:#4d4d4d}
:where(.hw-original) .metric-item-detail strong{display:block;margin-bottom:6px;font-size:13px;color:var(--red)}
:where(.hw-original) .metric-card{border:1px solid var(--line);padding:24px 22px 20px;display:flex;flex-direction:column;min-width:0;background:#fff}
:where(.hw-original) .metric-card .metric-label{font-size:calc(15px * var(--font-factor));font-weight:700;color:#4c5156}
:where(.hw-original) .metric-card .metric-value{margin-top:18px;font-size:calc(40px * var(--font-factor));line-height:1;font-weight:700;letter-spacing:-.04em}
:where(.hw-original) .metric-card .metric-value small{font-size:.42em;letter-spacing:0;margin-left:3px}
:where(.hw-original) .metric-card .metric-note{margin-top:12px;font-size:calc(13px * var(--font-factor));line-height:1.5;color:var(--muted)}
:where(.hw-original) .metric-card .metric-foot{margin-top:auto;padding-top:14px;border-top:1px solid #eceeef;font-size:12px;color:var(--red);font-weight:700}
:where(.hw-original) .metric-extra{display:none}
:where(.hw-original) .transform-layout{height:398px;display:grid;grid-template-columns:1fr 158px 1fr;gap:20px}
:where(.hw-original) .state-panel{border:1px solid var(--line);padding:24px 26px;background:#fff}
:where(.hw-original) .state-panel.after{border-top:4px solid var(--red);padding-top:21px}
:where(.hw-original) .state-head{display:flex;align-items:flex-end;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:16px}
:where(.hw-original) .state-title{font-size:24px;font-weight:700}
:where(.hw-original) .state-sub{font-size:12px;color:var(--muted)}
:where(.hw-original) .state-list{margin-top:8px}
:where(.hw-original) .state-item{display:grid;grid-template-columns:26px 1fr;gap:10px;padding:13px 0;border-bottom:1px solid #eceeef}
:where(.hw-original) .state-item:last-child{border-bottom:0}
:where(.hw-original) .state-item .item-no{font-size:12px;color:#a0a5aa;padding-top:3px}
:where(.hw-original) .state-item strong{display:block;font-size:calc(16px * var(--font-factor));margin-bottom:4px}
:where(.hw-original) .state-item span{display:block;font-size:calc(13px * var(--font-factor));line-height:1.45;color:var(--muted)}
:where(.hw-original) .transform-middle{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px}
:where(.hw-original) .transform-arrow{width:64px;height:64px;border-radius:50%;background:var(--red);color:#fff;display:flex;align-items:center;justify-content:center;font-size:34px;font-weight:700}
:where(.hw-original) .driver{width:100%;padding:10px 8px;border:1px solid #e5b6b9;background:var(--red-soft);color:var(--red);text-align:center;font-size:13px;font-weight:700}
:where(.hw-original) .outcome-band{height:58px;margin-top:16px;background:var(--soft);display:flex;align-items:center;padding:0 24px;gap:18px;border-left:4px solid var(--red)}
:where(.hw-original) .outcome-band strong{font-size:17px}
:where(.hw-original) .outcome-band span{font-size:14px;color:var(--muted)}
:where(.hw-original) .layers-layout{height:100%;display:grid;grid-template-columns:850px 1fr;gap:28px}
:where(.hw-original) .layer-canvas{display:flex;flex-direction:column;justify-content:center;gap:10px;position:relative;padding:4px 0}
:where(.hw-original) .layer{min-height:76px;display:grid;grid-template-columns:142px 1fr;background:var(--soft);border:1px solid var(--line);transition:width .2s}
:where(.hw-original) .layer .layer-name{background:#303338;color:#fff;display:flex;align-items:center;padding:14px 18px;font-size:17px;font-weight:700}
:where(.hw-original) .layer:nth-child(2) .layer-name{background:#54585d}
:where(.hw-original) .layer:nth-child(3) .layer-name{background:#777c81}
:where(.hw-original) .layer:nth-child(4) .layer-name{background:var(--red)}
:where(.hw-original) .layer-items{display:flex;align-items:center;gap:8px;padding:12px 14px}
:where(.hw-original) .layer-item{flex:1;min-width:0;padding:10px 8px;background:#fff;border:1px solid #e1e3e6;text-align:center;font-size:calc(13px * var(--font-factor));line-height:1.35}
:where(.hw-original) .layer-notes{border-left:1px solid var(--line);padding-left:24px;display:flex;flex-direction:column;justify-content:center;gap:20px}
:where(.hw-original) .layer-note .note-title{font-size:15px;font-weight:700;margin-bottom:6px}
:where(.hw-original) .layer-note p{margin:0;font-size:13px;line-height:1.5;color:var(--muted)}
:where(.hw-original) .house-roof,:where(.hw-original) .house-foundation{display:none}
:where(.hw-original) .layer-canvas[data-variant="pyramid"] .layer{margin-left:auto;margin-right:auto}
:where(.hw-original) .layer-canvas[data-variant="pyramid"] .layer:nth-child(2){width:62%}
:where(.hw-original) .layer-canvas[data-variant="pyramid"] .layer:nth-child(3){width:74%}
:where(.hw-original) .layer-canvas[data-variant="pyramid"] .layer:nth-child(4){width:86%}
:where(.hw-original) .layer-canvas[data-variant="pyramid"] .layer:nth-child(5){width:100%}
:where(.hw-original) .layer-canvas[data-variant="pyramid"] .layer{grid-template-columns:126px 1fr}
:where(.hw-original) .layer-canvas[data-variant="house"]{padding-top:56px;padding-bottom:40px}
:where(.hw-original) .layer-canvas[data-variant="house"] .house-roof{display:flex;position:absolute;left:15%;right:15%;top:0;height:52px;align-items:center;justify-content:center;background:var(--ink);color:#fff;font-size:17px;font-weight:700;clip-path:polygon(50% 0,100% 100%,0 100%);padding-top:16px}
:where(.hw-original) .layer-canvas[data-variant="house"] .house-foundation{display:flex;position:absolute;left:0;right:0;bottom:0;height:34px;align-items:center;justify-content:center;background:var(--red);color:#fff;font-size:14px;font-weight:700;letter-spacing:.08em}
:where(.hw-original) .table-wrap{height:100%;display:flex;flex-direction:column}
:where(.hw-original) table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:calc(14px * var(--font-factor))}
:where(.hw-original) thead th{background:var(--red);color:#fff;text-align:left;padding:11px 16px;font-size:14px;font-weight:700;border-right:1px solid #ffffff35}
:where(.hw-original) thead th:last-child{border-right:0}
:where(.hw-original) tbody td{padding:9px 16px;border-bottom:1px solid var(--line);border-right:1px solid #eceeef;line-height:1.35;vertical-align:middle}
:where(.hw-original) tbody td:last-child{border-right:0}
:where(.hw-original) tbody tr:nth-child(even):not(.group-row){background:#fafafa}
:where(.hw-original) tbody .group-row td{background:#f0f1f2;color:#44484d;font-size:12px;font-weight:700;letter-spacing:.08em;padding-top:6px;padding-bottom:6px}
:where(.hw-original) .cell-title{font-weight:700}
:where(.hw-original) .cell-sub{display:block;color:var(--muted);font-size:12px;margin-top:3px}
:where(.hw-original) .status{display:inline-block;padding:4px 9px;font-size:12px;font-weight:700;border:1px solid var(--line)}
:where(.hw-original) .status.high{color:var(--red);border-color:#e6b3b6;background:var(--red-soft)}
:where(.hw-original) .table-foot{margin-top:auto;display:flex;justify-content:space-between;align-items:center;padding-top:12px;color:var(--muted);font-size:12px}
:where(.hw-original) .radial-canvas{position:relative;width:100%;height:100%}
:where(.hw-original) .radial-links{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
:where(.hw-original) .radial-center{position:absolute;width:190px;height:120px;border-radius:60px;background:var(--ink);color:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;z-index:2;box-shadow:0 0 0 12px #fff,0 0 0 13px var(--line)}
:where(.hw-original) .radial-center strong{font-size:21px}
:where(.hw-original) .radial-center span{font-size:12px;color:#cfd2d5;margin-top:7px}
:where(.hw-original) .radial-node{position:absolute;width:176px;min-height:78px;background:#fff;border:1px solid var(--line);padding:13px 14px 12px 48px;z-index:2}
:where(.hw-original) .radial-node .node-no{position:absolute;left:13px;top:16px;width:25px;height:25px;border-radius:50%;background:var(--red-soft);color:var(--red);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700}
:where(.hw-original) .radial-node strong{display:block;font-size:15px;margin-bottom:5px}
:where(.hw-original) .radial-node span{display:block;font-size:12px;line-height:1.35;color:var(--muted)}
:where(.hw-original) .radial-caption{position:absolute;left:50%;bottom:2px;transform:translateX(-50%);font-size:12px;color:var(--muted);white-space:nowrap}
:where(.hw-original) .timeline{height:100%;position:relative;padding:0 16px}
:where(.hw-original) .timeline-track{position:relative;height:410px;display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:12px}
:where(.hw-original) .timeline-track:before{content:"";position:absolute;left:0;right:0;top:50%;height:2px;background:#cdd1d5}
:where(.hw-original) .timeline-track:after{content:"";position:absolute;right:-2px;top:calc(50% - 5px);border-left:12px solid var(--red);border-top:6px solid transparent;border-bottom:6px solid transparent}
:where(.hw-original) .milestone{position:relative;height:100%}
:where(.hw-original) .mile-dot{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:16px;height:16px;border-radius:50%;background:#fff;border:4px solid var(--red);z-index:2}
:where(.hw-original) .mile-card{position:absolute;left:0;right:0;height:156px;padding:18px 16px;border:1px solid var(--line);background:#fff}
:where(.hw-original) .milestone:nth-child(odd) .mile-card{top:12px;border-top:3px solid var(--red)}
:where(.hw-original) .milestone:nth-child(even) .mile-card{bottom:12px}
:where(.hw-original) .mile-card:before{content:"";position:absolute;left:50%;width:1px;height:36px;background:#bfc4c8}
:where(.hw-original) .milestone:nth-child(odd) .mile-card:before{bottom:-36px}
:where(.hw-original) .milestone:nth-child(even) .mile-card:before{top:-36px}
:where(.hw-original) .mile-date{font-size:13px;color:var(--red);font-weight:700}
:where(.hw-original) .mile-card h3{margin:10px 0 8px;font-size:calc(16px * var(--font-factor));line-height:1.3}
:where(.hw-original) .mile-card p{margin:0;font-size:calc(12px * var(--font-factor));line-height:1.5;color:var(--muted)}
:where(.hw-original) .timeline.four .milestone[data-index="4"],:where(.hw-original) .timeline.four .milestone[data-index="5"]{display:none}
:where(.hw-original) .timeline-legend{height:36px;display:flex;align-items:center;justify-content:center;gap:28px;font-size:12px;color:var(--muted)}
:where(.hw-original) .legend-item{display:flex;align-items:center;gap:7px}
:where(.hw-original) .legend-dot{width:8px;height:8px;background:var(--red)}
:where(.hw-original) .process-wrap{height:100%;display:flex;flex-direction:column}
:where(.hw-original) .process-chain{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;height:340px}
:where(.hw-original) .process-step{position:relative;border:1px solid var(--line);background:#fff;display:flex;flex-direction:column;min-width:0}
:where(.hw-original) .step-head{height:64px;background:#34373b;color:#fff;padding:12px 14px;display:flex;align-items:center;gap:9px}
:where(.hw-original) .process-step:nth-child(-n+2) .step-head{background:#60656a}
:where(.hw-original) .process-step:last-child .step-head{background:var(--red)}
:where(.hw-original) .step-no{font-size:12px;color:#e3e5e7}
:where(.hw-original) .step-head strong{font-size:15px}
:where(.hw-original) .step-body{padding:18px 14px 12px;flex:1}
:where(.hw-original) .step-body p{margin:0 0 14px;font-size:calc(13px * var(--font-factor));line-height:1.5;color:#44494e}
:where(.hw-original) .step-meta{border-top:1px solid #eceeef;padding:10px 14px;font-size:11px;line-height:1.6;color:var(--muted)}
:where(.hw-original) .step-output{padding:10px 14px;background:var(--soft);font-size:12px;line-height:1.4}
:where(.hw-original) .step-output strong{color:var(--red)}
:where(.hw-original) .process-chain[data-variant="chevron"]{gap:5px}
:where(.hw-original) .process-chain[data-variant="chevron"] .process-step{border:0}
:where(.hw-original) .process-chain[data-variant="chevron"] .step-head{clip-path:polygon(0 0,calc(100% - 16px) 0,100% 50%,calc(100% - 16px) 100%,0 100%,12px 50%);padding-left:20px;height:76px}
:where(.hw-original) .process-chain[data-variant="chevron"] .step-body{border-left:1px solid var(--line);border-right:1px solid var(--line)}
:where(.hw-original) .process-chain[data-variant="chevron"] .step-meta{border-left:1px solid var(--line);border-right:1px solid var(--line)}
:where(.hw-original) .process-chain[data-variant="chevron"] .step-output{border:1px solid var(--line);border-top:0}
:where(.hw-original) .process-chain[data-variant="value"]{gap:0}
:where(.hw-original) .process-chain[data-variant="value"] .process-step{border:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
:where(.hw-original) .process-chain[data-variant="value"] .step-head{background:#fff;color:var(--ink);border-bottom:3px solid var(--red);height:58px;padding-left:8px}
:where(.hw-original) .process-chain[data-variant="value"] .step-no{color:var(--red);font-weight:700}
:where(.hw-original) .process-chain[data-variant="value"] .step-body{padding-left:8px;padding-right:12px}
:where(.hw-original) .process-chain[data-variant="value"] .step-meta,:where(.hw-original) .process-chain[data-variant="value"] .step-output{padding-left:8px;background:#fff}
:where(.hw-original) .feedback{height:58px;margin-top:20px;border:1px dashed #c5c9cd;display:flex;align-items:center;padding:0 18px;gap:16px;color:var(--muted);font-size:13px}
:where(.hw-original) .feedback strong{color:var(--red)}
:where(.hw-original) .feedback-arrow{font-size:23px;color:var(--red)}
:where(.hw-original) .process-summary{margin-top:auto;display:flex;gap:28px;font-size:12px;color:var(--muted)}
:where(.hw-original) .process-summary strong{color:var(--ink);font-size:15px;margin-right:6px}
:where(.hw-original) .metric-hero{background:linear-gradient(135deg,#fafafa 0%,#e0e0e0 58%,#c6c6c6 100%);color:#4d4d4d;border:1px solid #c6c6c6}
:where(.hw-original) .metric-hero:after{border-color:#4d4d4d08}
:where(.hw-original) .metric-hero .hero-desc{color:#666}
:where(.hw-original) .metric-hero .hero-delta{color:var(--red)}
:where(.hw-original) .metric-hero .hero-bars{border-bottom-color:#4d4d4d30}
:where(.hw-original) .metric-hero .hero-bars i{background:#a3a3a3}
:where(.hw-original) .metric-hero .hero-bars i:last-child{background:var(--red)}
:where(.hw-original) .layer .layer-name,:where(.hw-original) .layer:nth-child(2) .layer-name,:where(.hw-original) .layer:nth-child(3) .layer-name,:where(.hw-original) .layer:nth-child(5) .layer-name{background:linear-gradient(135deg,#f2f2f2,#d9d9d9);color:#4d4d4d}
:where(.hw-original) .layer:nth-child(3) .layer-name{background:linear-gradient(135deg,#e0e0e0,#c6c6c6)}
:where(.hw-original) .layer:nth-child(4) .layer-name{background:var(--red);color:#fff}
:where(.hw-original) .layer-canvas[data-variant="house"] .house-roof{background:linear-gradient(135deg,#f2f2f2,#c6c6c6);color:#4d4d4d}
