:where(.hw-original) .media-bento-title.red-band{background:var(--red);color:#fff}
:where(.hw-original) .media-bento-body{padding:16px 18px}
:where(.hw-original) .media-bento-body h3{margin:0 0 9px;font-size:18px;line-height:1.35;color:#4d4d4d}
:where(.hw-original) .media-bento-body p{margin:0;font-size:calc(13px * var(--font-factor));line-height:1.55;color:#666}
:where(.hw-original) .media-bento-art{position:relative;margin:0;background:#f2f2f2}
:where(.hw-original) .media-bento-art svg{display:block;width:100%;height:100%}
:where(.hw-original) .media-bento-art figcaption{position:absolute;left:16px;bottom:16px;padding:8px 12px;background:#fff;border:1px solid #d9d9d9;color:#4d4d4d;font-size:12px;font-weight:700}
:where(.hw-original).capacity-compact .media-bento-title{padding:9px 12px;font-size:13px}
:where(.hw-original).capacity-compact .media-bento-body{padding:12px 14px}
:where(.hw-original).capacity-compact .media-bento-body h3{font-size:15px;margin-bottom:6px}
:where(.hw-original).capacity-compact .media-bento-body p{font-size:11.5px}
:where(.hw-original) .chart-layout{height:100%;display:grid;gap:14px;align-items:stretch}
:where(.hw-original) .chart-card,:where(.hw-original) .chart-text-card{height:100%;border:1px solid #c6c6c6;background:#fff;display:flex;flex-direction:column;min-width:0;overflow:hidden}
:where(.hw-original) .chart-title,:where(.hw-original) .chart-text-title{padding:11px 15px;background:linear-gradient(135deg,#f2f2f2,#d9d9d9);color:#4d4d4d;font-size:14px;font-weight:700}
:where(.hw-original) .chart-text-title.red-band{background:var(--red);color:#fff}
:where(.hw-original) .chart-plot{position:relative;flex:1;min-height:0;padding:18px 18px 8px}
:where(.hw-original) .chart-plot svg{display:block;width:100%;height:100%;min-height:160px}
:where(.hw-original) .chart-unit{position:absolute;left:18px;top:12px;font-size:11px;color:#777}
:where(.hw-original) .chart-x-labels{display:flex;justify-content:space-between;padding:0 18px 13px;font-size:11px;color:#777}
:where(.hw-original) .chart-legend{display:flex;flex-wrap:wrap;gap:8px 16px;padding:0 18px 14px;font-size:11px;color:#666}
:where(.hw-original) .chart-legend span{display:flex;align-items:center;gap:6px}
:where(.hw-original) .chart-legend i{width:9px;height:9px;display:inline-block}
:where(.hw-original) .chart-text-body{padding:15px 17px}
:where(.hw-original) .chart-text-body h3{margin:0 0 8px;font-size:17px;line-height:1.35;color:#4d4d4d}
:where(.hw-original) .chart-text-body p{margin:0;font-size:calc(12.5px * var(--font-factor));line-height:1.5;color:#666}
:where(.hw-original) .hbar-list{flex:1;display:flex;flex-direction:column;justify-content:center;gap:22px;padding:20px}
:where(.hw-original) .hbar-row{display:grid;grid-template-columns:86px 1fr 38px;align-items:center;gap:12px;font-size:12px;color:#4d4d4d}
:where(.hw-original) .hbar-track{height:20px;background:#f0f0f0}
:where(.hw-original) .hbar-track i{display:block;height:100%;background:#a3a3a3}
:where(.hw-original) .hbar-row:last-child .hbar-track i{background:var(--red)}
:where(.hw-original) .hbar-value{text-align:right;font-weight:700}
:where(.hw-original) .donut-center{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);text-align:center;color:#4d4d4d}
:where(.hw-original) .donut-center strong{display:block;font-size:38px;line-height:1}
:where(.hw-original) .donut-center span{font-size:11px;color:#777}
:where(.hw-original) .radar-label{position:absolute;font-size:11px;color:#666;white-space:nowrap}
:where(.hw-original) .radar-label.top{left:50%;top:4px;transform:translateX(-50%)}
:where(.hw-original) .radar-label.right{right:2px;top:50%;transform:translateY(-50%)}
:where(.hw-original) .radar-label.bottom{left:50%;bottom:4px;transform:translateX(-50%)}
:where(.hw-original) .radar-label.left{left:2px;top:50%;transform:translateY(-50%)}
:where(.hw-original).capacity-compact .chart-title,:where(.hw-original).capacity-compact .chart-text-title{padding:8px 12px;font-size:12px}
:where(.hw-original).capacity-compact .chart-text-body{padding:11px 13px}
:where(.hw-original).capacity-compact .chart-text-body h3{font-size:14px;margin-bottom:5px}
:where(.hw-original).capacity-compact .chart-text-body p{font-size:11px}
.hw-original .source{bottom:53px}
:where(.hw-original) .slide-footer{position:absolute;left:77px;top:670px;height:20px;display:flex;align-items:center;color:#1d1d1b;font-family:Arial,sans-serif;font-size:12.2px;line-height:1;font-weight:400}
:where(.hw-original) .slide-footer .page-number{min-width:14px;font-variant-numeric:tabular-nums}
:where(.hw-original) .slide-footer .copyright{margin-left:20px;white-space:nowrap}
:where(.hw-original) .embed .hw-original{box-shadow:none}
:where(.hw-original) [data-hw-source-id="chart-data-dialog"]{width:520px;max-width:calc(100vw - 40px);border:1px solid #c6c6c6;padding:24px;color:#4d4d4d;box-shadow:0 18px 60px #0003}
:where(.hw-original) [data-hw-source-id="chart-data-dialog"]::backdrop{background:#191b1e66}
:where(.hw-original) [data-hw-source-id="chart-data-dialog"] h2{margin:0 0 8px;font-size:20px}
:where(.hw-original) [data-hw-source-id="chart-data-dialog"] p{margin:0 0 14px;font-size:12px;line-height:1.5;color:#777}
:where(.hw-original) [data-hw-source-id="chart-data-input"]{width:100%;height:220px;resize:vertical;border:1px solid #c6c6c6;padding:12px;font:13px/1.6 Consolas,monospace;color:#333}
:where(.hw-original) [data-hw-source-id="chart-data-error"]{min-height:20px;margin-top:8px;color:var(--red);font-size:12px}
:where(.hw-original) .chart-dialog-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:12px}
:where(.hw-original) .chart-dialog-actions button{border:1px solid #c6c6c6;background:#fff;padding:8px 16px}
:where(.hw-original) .chart-dialog-actions button.primary{background:var(--red);border-color:var(--red);color:#fff}
